-- Protected with Bytecode+Base64
local _P = ""
local _K1 = 201
local _K2 = 40

local function _run()
    local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local clean_p = string.gsub(_P, '[^'..b..'=]', '')
    
    local dec_b64 = (clean_p:gsub('.', function(x)
        if (x == '=') then return '' end
        local r, f = '', (b:find(x) - 1)
        for i = 6, 1, -1 do r = r .. (f % 2^i - f % 2^(i-1) >= 1 and '1' or '0') end
        return r
    end):gsub('%d%d%d%d%d%d%d%d', function(x)
        local c = 0
        for i = 1, 8 do c = c + (x:sub(i, i) == '1' and 2^(8-i) or 0) end
        return string.char(c)
    end))
    
    local parts = {}
    for i = 1, #dec_b64 do
        local enc = dec_b64:byte(i)
        local orig = (enc - _K2) % 256
        orig = (orig - _K1 - (i * 7)) % 256
        parts[i] = string.char(orig)
    end
    
    local raw_bytecode = table.concat(parts)
    _P, _K1, _K2, dec_b64, parts = nil, nil, nil, nil, nil
    
    local ls = loadstring or load
    local fn, err = ls(raw_bytecode, "=protected")
    if fn then
        fn()
    else
        error("VM Error: " .. tostring(err))
    end
end

_run()
